      SUBROUTINE FND100C---- LOCATE NEXT REFERENCE TO A PRECEDING PARAMETERC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'ICOPY.CIN'      INCLUDE 'LIMITS.CIN'C      IEND = IDLIM      DO 20 III = IB100, IEND      IF (TIE(III) .EQ. 100) THEN        IREF = IDATA(III)        IF (I100 .EQ. 0 .OR. (IREF .GT. I100 .AND. I100 .LT. IB100)     1      .OR. (IREF .LT. I100 .AND. IREF .GE. IB100)) THEN          I100 = IREF        ENDIF      ENDIF   20 CONTINUE         IB100 = I100 + 1      RETURN      END